Here is the recipe JSON:
{
  "recipe_name": "Classic Garlic Bread",
  "ingredients": [
    "1 loaf of Italian bread",
    "3 cloves of garlic, minced",
    "1/2 cup of butter, softened",
    "1/2 cup of grated Parmesan cheese",
    "Salt and pepper to taste"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "Preheat the oven to 350\u00b0F (175\u00b0C).",
      "time": "5 minutes",
      "tip": "Make sure the oven is preheated to the correct temperature for even cooking."
    },
    {
      "step_number": 2,
      "instruction": "Slice the Italian bread into 1-inch thick slices.",
      "time": "2 minutes",
      "tip": "Use a serrated knife to get clean cuts."
    },
    {
      "step_number": 3,
      "instruction": "In a small bowl, mix together the minced garlic and softened butter until well combined.",
      "time": "2 minutes",
      "tip": "Use high-quality garlic for the best flavor."
    },
    {
      "step_number": 4,
      "instruction": "Spread the garlic butter mixture evenly onto each bread slice.",
      "time": "3 minutes",
      "tip": "Make sure to spread the mixture all the way to the edges."
    },
    {
      "step_number": 5,
      "instruction": "Sprinkle the grated Parmesan cheese over the garlic butter.",
      "time": "1 minute",
      "tip": "Use freshly grated cheese for the best flavor."
    },
    {
      "step_number": 6,
      "instruction": "Place the bread slices on a baking sheet lined with parchment paper.",
      "time": "2 minutes",
      "tip": "Leave some space between each slice for even cooking."
    },
    {
      "step_number": 7,
      "instruction": "Bake the garlic bread in the preheated oven for 10-12 minutes, or until golden brown.",
      "time": "10-12 minutes",
      "tip": "Keep an eye on the bread to prevent burning."
    }
  ]
}
